              : e.status === 422
              ? 'Only a steward can approve a pending claim.'
              : e.status === 409 && action === 'approve'
              ? 'Only a pending claim can be approved.'
              : e.status === 423
              ? 'That claim is dated in a closed period.'
              : e.status === 409
