            : e.status === 422
              ? 'That claim is dated after its person is retired.'
              : e.status === 423
              ? 'That claim is dated in a closed period.'
              : e.status === 409
                ? 'Only a draft claim can be edited. To change it, void it and add a new one.'
                : 'Could not save that claim.',
        );
      },
    });
  }
